{
 "paper_title": "Some Methods for Classification and Analysis of Multivariate Observations",
 "authors_year": "J. MacQueen, 1967",
 "research_question": "How can an N-dimensional population be partitioned into k sets on the basis of a sample using the k-means procedure, and what is the asymptotic behavior of this procedure?",
 "context": "The study of partitioning multivariate observations into k sets to minimize within-class variance, connecting optimal information structures, similarity grouping, non-linear prediction, and nonparametric tests.",
 "methods": [
  "Defining the k-means partitioning process and minimum distance partitions",
  "Applying martingale theory to prove almost sure convergence of sample means and within-class variance",
  "Developing algorithmic modifications involving coarsening (C) and refinement (R) parameters",
  "Proposing a scrambled dimension test for independence",
  "Extending the k-means concept and centroids to general metric spaces"
 ],
 "main_findings": [
  "The sequence of expected within-class variances W(x^n) converges almost surely to V(x) for an unbiased k-point under independent sampling.",
  "The k-means procedure is computationally economical and feasible for processing very large samples on digital computers.",
  "Practical modifications such as coarsening and refinement parameters help control the number of groups dynamically during sample processing."
 ],
 "assumptions": [
  "The probability measure p is absolutely continuous with respect to Lebesgue measure on E_N.",
  "p(R) = 1 for a closed and bounded convex set R subset of E_N, and p(A) > 0 for every open set A subset of R."
 ],
 "limitations_explicit": [
  "In general, the k-means procedure will not necessarily converge to an optimal partition.",
  "A computer program was not available to execute the scrambling test empirically at large scale in the current study."
 ],
 "potential_open_questions": [
  {
   "question": "Does the k-means procedure always avoid slow indefinite oscillation around the center in symmetric configurations?",
   "why_unresolved": "Theorem 1 does not quite permit eliminating the possibility that the two means oscillate slowly but indefinitely around the center.",
   "evidence": "Theorem 1 provides for a.s. convergence of the sum, but leaves open slow oscillation around the center in certain symmetric configurations.",
   "sections": [
    "2.3"
   ]
  },
  {
   "question": "What is the exact statistical power of the proposed scrambled dimension test for independence?",
   "why_unresolved": "A computer program was not available to do the scrambling and further testing of this method was not undertaken.",
   "evidence": "A computer program was not available to do the scrambling, and its being inconvenient to set up large numbers of scrambled samples using punched cards, further testing of this method was not undertaken.",
   "sections": [
    "3.4"
   ]
  }
 ],
 "candidate_hypotheses": [
  {
   "hypothesis": "For fixed marginal distributions, the within-class variance for the optimal partition is maximal when the joint distribution is actually the product of the marginals.",
   "rationale": "Intuition and inspection of obvious examples suggest that scrambling independent dimensions increases the within-class variance.",
   "evidence": "On the encouraging side is the related conjecture, that for fixed marginal distributions, the within-class variance for the optimal partition as defined in section 1 is maximal when the joint distribution is actually the product of the marginals.",
   "sections": [
    "3.4"
   ]
  }
 ]
}

